-- ===== migrations/20261020120200_partb_call_logs.sql =====
-- =====================================================================
-- TNV Hub Portal - Phase 1 Backend & Database Migration
-- Part B: Steps 8 & 9 / Task T6 - Call Logs, log_call RPC, admin_queue & admin_followups
-- Spec: TNV_Hub_Backend_Database_Spec (1).pdf (Sections 4.2, 4.4, 5, 7, 10)
-- Journey: TNV_End_to_End_Journey.pdf (Part B, Steps 8 & 9)
-- =====================================================================

-- 1. Create call_logs table
create table if not exists call_logs (
    id uuid primary key default gen_random_uuid(),
    profile_id uuid not null references profiles(id) on delete cascade,
    admin_id uuid not null references profiles(id) on delete cascade,
    outcome call_outcome not null,
    callback_at timestamptz,
    note text,
    created_at timestamptz not null default now(),
    -- Constraint: callback_at is required when outcome is scheduled
    constraint chk_scheduled_callback check (
        outcome <> 'scheduled' or callback_at is not null
    )
);

-- Index for fast lookup of applicant call history
create index if not exists idx_call_logs_profile_id on call_logs (profile_id, created_at desc);

-- 2. Enable Row-Level Security on call_logs
alter table call_logs enable row level security;

-- Admins only policy (applicants get zero access)
drop policy if exists "Admins can view call logs" on call_logs;
create policy "Admins can view call logs"
    on call_logs
    for select
    using (is_admin());

drop policy if exists "Admins can insert call logs" on call_logs;
create policy "Admins can insert call logs"
    on call_logs
    for insert
    with check (is_admin() or coalesce(current_setting('request.jwt.claim.role', true), '') = 'service_role');

-- 3. RPC: log_call(profile_id, outcome, callback_at, note)
-- Caller: Admin (checked inside the function)
-- Rule: Scheduled requires callback_at; unlimited attempts allowed per applicant.
create or replace function log_call(
    profile_id uuid,
    outcome call_outcome,
    callback_at timestamptz default null,
    note text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
    v_admin_id uuid;
    v_log_id uuid;
    v_created_at timestamptz;
begin
    -- 1. Verify caller is an admin
    if not is_admin() and coalesce(current_setting('request.jwt.claim.role', true), '') <> 'service_role' then
        raise exception 'Access denied: Admin role required to log calls';
    end if;

    -- 2. Identify acting admin
    v_admin_id := auth.uid();
    if v_admin_id is null then
        -- If called by service role or system without jwt, fallback to finding a master_admin or the profile itself
        select id into v_admin_id from profiles where role = 'master_admin' limit 1;
        if v_admin_id is null then
            v_admin_id := profile_id;
        end if;
    end if;

    -- 3. Check applicant profile exists
    if not exists (select 1 from profiles where id = profile_id) then
        raise exception 'Applicant profile % does not exist', profile_id;
    end if;

    -- 4. Check business rule: outcome 'scheduled' requires callback_at
    if outcome = 'scheduled' and callback_at is null then
        raise exception 'callback_at is required when outcome is scheduled';
    end if;

    -- 5. Insert call log entry
    insert into call_logs (
        profile_id,
        admin_id,
        outcome,
        callback_at,
        note,
        created_at
    ) values (
        profile_id,
        v_admin_id,
        outcome,
        callback_at,
        note,
        now()
    )
    returning id, created_at into v_log_id, v_created_at;

    return jsonb_build_object(
        'success', true,
        'id', v_log_id,
        'profile_id', profile_id,
        'admin_id', v_admin_id,
        'outcome', outcome,
        'callback_at', callback_at,
        'note', note,
        'created_at', v_created_at
    );
end;
$$;

grant execute on function log_call(uuid, call_outcome, timestamptz, text) to authenticated, service_role;

-- 4. Admin Queue View: admin_queue
-- Includes paid & unpaid applicants, masked Aadhaar, and latest call outcome
create or replace view admin_queue as
select
    p.id,
    p.full_name,
    p.username,
    p.email,
    p.phone,
    p.district_id,
    d.name as district_name,
    p.aadhaar_last4,
    p.status as application_status,
    p.status,
    p.role,
    p.wing_id,
    w.name as wing_name,
    p.membership_paid,
    p.created_at,
    p.photo_path,
    p.affiliation,
    p.category,
    p.assembly_constituency,
    p.panchayat,
    p.occupation,
    p.preferred_designation,
    p.wing_to_join,
    p.department,
    p.mode_of_work,
    coalesce(cl.outcome::text, 'not_called') as call_status,
    cl.callback_at as latest_callback_at,
    cl.created_at as latest_call_at,
    cl.note as latest_call_note,
    cl.admin_id as latest_caller_id,
    (
        select count(*)
        from call_logs
        where profile_id = p.id
    ) as total_call_attempts
from profiles p
left join districts d on d.id = p.district_id
left join wings w on w.id = p.wing_id
left join lateral (
    select outcome, callback_at, created_at, note, admin_id
    from call_logs
    where profile_id = p.id
    order by created_at desc
    limit 1
) cl on true;

comment on view admin_queue is 'Admin review queue with paid & unpaid applicants, masked Aadhaar, and latest call attempt outcome.';

-- 5. Admin Follow-ups View: admin_followups
-- Lists scheduled callbacks that are due and no-answer applicants older than 24 hours
create or replace view admin_followups as
select *
from admin_queue
where status = 'pending'
  and (
      (call_status = 'scheduled' and latest_callback_at <= now())
      or
      (call_status = 'no_answer' and latest_call_at <= now() - interval '24 hours')
  );

comment on view admin_followups is 'Scheduled callbacks that are due and uncontacted applicants past 24 hours.';

-- ===== migrations/20261020120300_partb_scoring.sql =====
-- =====================================================================
-- TNV Hub Portal - Phase 1 Backend & Database Migration
-- Part B: Step 10 / Task T7 - Interview Questions, Scores & save_scores RPC
-- Spec: TNV_Hub_Backend_Database_Spec (1).pdf (Sections 4.2, 4.4, 5, 7, 10)
-- Journey: TNV_End_to_End_Journey.pdf (Part B, Step 10)
-- =====================================================================

-- 1. Create interview_questions table
create table if not exists interview_questions (
    id serial primary key,
    position int not null unique,
    text text not null,
    active boolean not null default true,
    created_at timestamptz not null default now()
);

-- Enable Row Level Security on interview_questions
alter table interview_questions enable row level security;

-- Admin-only policy (applicants cannot read or write questions)
drop policy if exists "Admins can view interview questions" on interview_questions;
create policy "Admins can view interview questions"
    on interview_questions
    for select
    using (is_admin());

drop policy if exists "Admins can manage interview questions" on interview_questions;
create policy "Admins can manage interview questions"
    on interview_questions
    for all
    using (is_admin())
    with check (is_admin());

-- 2. Create interview_scores table
create table if not exists interview_scores (
    profile_id uuid not null references profiles(id) on delete cascade,
    question_id int not null references interview_questions(id) on delete cascade,
    score numeric(3,1) not null,
    note text,
    scored_by uuid references profiles(id) on delete set null,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    primary key (profile_id, question_id),
    constraint chk_score check (score in (0, 0.5, 1))
);

-- Enable Row Level Security on interview_scores
alter table interview_scores enable row level security;

-- Admin-only policy for scores
drop policy if exists "Admins can view interview scores" on interview_scores;
create policy "Admins can view interview scores"
    on interview_scores
    for select
    using (is_admin());

drop policy if exists "Admins can manage interview scores" on interview_scores;
create policy "Admins can manage interview scores"
    on interview_scores
    for all
    using (is_admin())
    with check (is_admin());

-- 3. RPC: save_scores(p_profile_id, scores)
-- Caller: Admin
-- Contract: Upserts scores for an applicant.
-- Rules: Score must be exactly 0, 0.5, or 1. Question must be active. scored_by is auth.uid().
drop function if exists save_scores(uuid, jsonb);
create or replace function save_scores(
    p_profile_id uuid,
    scores jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
    v_admin_id uuid;
    v_item jsonb;
    v_question_id int;
    v_score numeric(3,1);
    v_note text;
    v_is_active boolean;
    v_total_score numeric(4,1);
    v_scored_count int;
    v_active_count int;
begin
    -- 1. Check caller is an admin
    if not is_admin() and coalesce(current_setting('request.jwt.claim.role', true), '') <> 'service_role' and current_user not in ('postgres', 'supabase_admin') then
        raise exception 'Access denied: Admin role required to record scores';
    end if;

    -- 2. Identify scoring admin
    v_admin_id := auth.uid();
    if v_admin_id is null then
        select id into v_admin_id from profiles where role in ('master_admin', 'dept_admin') limit 1;
        if v_admin_id is null then
            v_admin_id := p_profile_id;
        end if;
    end if;

    -- 3. Check applicant profile exists
    if not exists (select 1 from profiles where id = p_profile_id) then
        raise exception 'Applicant profile % does not exist', p_profile_id;
    end if;

    -- 4. Validate input is a JSON array
    if jsonb_typeof(scores) <> 'array' then
        raise exception 'Scores input must be a JSON array of score objects';
    end if;

    -- 5. Iterate through score objects and validate each
    for v_item in select * from jsonb_array_elements(scores)
    loop
        v_question_id := (v_item->>'question_id')::int;
        if v_question_id is null then
            raise exception 'Each score object must include question_id';
        end if;

        -- Check score value: strictly 0, 0.5, or 1
        begin
            v_score := (v_item->>'score')::numeric(3,1);
        exception when others then
            raise exception 'Invalid score value: %. Score must be 0, 0.5, or 1', (v_item->>'score');
        end;

        if v_score not in (0, 0.5, 1) then
            raise exception 'Score value % is invalid. Score must be strictly 0, 0.5, or 1', v_score;
        end if;

        v_note := v_item->>'note';

        -- Verify question exists and is active
        select active into v_is_active
        from interview_questions
        where id = v_question_id;

        if v_is_active is null then
            raise exception 'Interview question % does not exist', v_question_id;
        end if;

        if not v_is_active then
            raise exception 'Interview question % is inactive and cannot be scored', v_question_id;
        end if;

        -- Upsert score (unambiguous column vs param names)
        insert into interview_scores (
            profile_id,
            question_id,
            score,
            note,
            scored_by,
            updated_at
        ) values (
            p_profile_id,
            v_question_id,
            v_score,
            v_note,
            v_admin_id,
            now()
        )
        on conflict (profile_id, question_id)
        do update set
            score = excluded.score,
            note = excluded.note,
            scored_by = excluded.scored_by,
            updated_at = now();
    end loop;

    -- 6. Compute running totals
    select coalesce(sum(s.score), 0), count(*)
    into v_total_score, v_scored_count
    from interview_scores s
    join interview_questions q on q.id = s.question_id
    where s.profile_id = p_profile_id
      and q.active = true;

    select count(*)
    into v_active_count
    from interview_questions
    where active = true;

    return jsonb_build_object(
        'success', true,
        'profile_id', p_profile_id,
        'total_score', v_total_score,
        'scored_count', v_scored_count,
        'active_questions_count', v_active_count,
        'is_complete', (v_scored_count >= v_active_count and v_active_count > 0)
    );
end;
$$;

grant execute on function save_scores(uuid, jsonb) to authenticated, service_role;

-- ===== migrations/20261020120400_partb_verification.sql =====
-- =====================================================================
-- TNV Hub Portal - Phase 1 Backend & Database Migration
-- Part B: Step 11 / Task T8 - Verifications, reveal_aadhaar RPC, and Atomic approve_applicant_tx RPC
-- Spec: TNV_Hub_Backend_Database_Spec (1).pdf (Sections 4.2, 4.4, 5, 6.3, 7, 10, 12)
-- Journey: TNV_End_to_End_Journey.pdf (Part B, Step 11)
-- =====================================================================

-- 1. Create verifications table
create table if not exists verifications (
    profile_id uuid primary key references profiles(id) on delete cascade,
    total_score numeric(4,1) not null,
    recommended_role app_role not null,
    approved_by uuid not null references profiles(id),
    approved_at timestamptz not null default now()
);

-- Enable Row Level Security on verifications
alter table verifications enable row level security;

-- Admins can view verifications
drop policy if exists "Admins can view verifications" on verifications;
create policy "Admins can view verifications"
    on verifications
    for select
    using (is_admin());

-- Admins & Service role can insert/update verifications
drop policy if exists "Admins and service role can insert verifications" on verifications;
create policy "Admins and service role can insert verifications"
    on verifications
    for all
    using (is_admin() or coalesce(current_setting('request.jwt.claim.role', true), '') = 'service_role')
    with check (is_admin() or coalesce(current_setting('request.jwt.claim.role', true), '') = 'service_role');

-- 2. RPC: reveal_aadhaar(id)
-- Caller: Master Admin ONLY (checked inside function; dept_admin is REFUSED)
-- Contract: Writes audit_log in the same transaction, returns aadhaar data.
create or replace function reveal_aadhaar(id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
    v_actor uuid;
    v_enc text;
    v_last4 text;
    v_full_name text;
begin
    -- 1. Master Admin verification (Strict: dept_admin and regular users cannot reveal)
    if not is_master_admin() and coalesce(current_setting('request.jwt.claim.role', true), '') <> 'service_role' then
        raise exception 'Access denied: Master Admin role strictly required to reveal Aadhaar';
    end if;

    -- 2. Fetch applicant Aadhaar data
    select aadhaar_enc, aadhaar_last4, full_name
    into v_enc, v_last4, v_full_name
    from profiles
    where profiles.id = reveal_aadhaar.id;

    if v_enc is null then
        raise exception 'Profile % not found', reveal_aadhaar.id;
    end if;

    -- 3. Actor identification
    v_actor := auth.uid();
    if v_actor is null then
        select p.id into v_actor from profiles p where p.role = 'master_admin' limit 1;
        if v_actor is null then
            v_actor := reveal_aadhaar.id;
        end if;
    end if;

    -- 4. Mandatory Audit Log entry (in the exact same atomic transaction)
    insert into audit_log (
        actor,
        action,
        target,
        detail,
        at
    ) values (
        v_actor,
        'reveal_aadhaar',
        reveal_aadhaar.id,
        jsonb_build_object(
            'target_name', v_full_name,
            'aadhaar_last4', v_last4,
            'revealed_at', now()
        ),
        now()
    );

    return jsonb_build_object(
        'success', true,
        'profile_id', reveal_aadhaar.id,
        'full_name', v_full_name,
        'aadhaar_enc', v_enc,
        'aadhaar_last4', v_last4
    );
end;
$$;

grant execute on function reveal_aadhaar(uuid) to authenticated, service_role;

-- 3. Atomic Database Transaction RPC: approve_applicant_tx
-- Called by Edge Function approve_applicant or Admin UI
-- Atomic Steps:
--   1. Check caller is admin (master_admin or dept_admin)
--   2. Check applicant exists and status is 'pending' (refuses already approved)
--   3. Verify EVERY active question in interview_questions has a recorded score
--   4. Calculate total score
--   5. Generate official TNV ID from sequence
--   6. Update profile: status='approved', role=p_role, wing_id, tnv_id
--   7. Upsert verifications row
--   8. Insert audit_log row
create or replace function approve_applicant_tx(
    p_profile_id uuid,
    p_role app_role,
    p_wing_id int default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
    v_admin_id uuid;
    v_status app_status;
    v_district_id int;
    v_full_name text;
    v_username text;
    v_email text;
    v_missing_questions int[];
    v_total_score numeric(4,1);
    v_scored_count int;
    v_active_count int;
    v_tnv_id text;
    v_final_wing_id int;
begin
    -- 1. Verify caller is an admin
    if not is_admin() and coalesce(current_setting('request.jwt.claim.role', true), '') <> 'service_role' then
        raise exception 'Access denied: Admin role required to approve applicants';
    end if;

    v_admin_id := auth.uid();
    if v_admin_id is null then
        select id into v_admin_id from profiles where role in ('master_admin', 'dept_admin') limit 1;
        if v_admin_id is null then
            v_admin_id := p_profile_id;
        end if;
    end if;

    -- 2. Fetch applicant profile & verify pending status
    select status, district_id, full_name, username, email, wing_id
    into v_status, v_district_id, v_full_name, v_username, v_email, v_final_wing_id
    from profiles
    where id = p_profile_id;

    if v_district_id is null then
        raise exception 'Profile % not found', p_profile_id;
    end if;

    if v_status <> 'pending' then
        raise exception 'Applicant cannot be approved: current status is "%" (only pending applicants can be approved)', v_status;
    end if;

    -- 3. Verify ALL active interview questions are scored
    select coalesce(array_agg(q.id order by q.position), array[]::int[])
    into v_missing_questions
    from interview_questions q
    where q.active = true
      and not exists (
          select 1
          from interview_scores s
          where s.profile_id = p_profile_id
            and s.question_id = q.id
      );

    if array_length(v_missing_questions, 1) > 0 then
        raise exception 'Scoring incomplete: applicant is missing scores for question ID(s): %', array_to_string(v_missing_questions, ', ');
    end if;

    -- 4. Calculate total score and counts
    select coalesce(sum(s.score), 0), count(*)
    into v_total_score, v_scored_count
    from interview_scores s
    join interview_questions q on q.id = s.question_id
    where s.profile_id = p_profile_id
      and q.active = true;

    select count(*)
    into v_active_count
    from interview_questions
    where active = true;

    -- 5. Generate official TNV ID
    v_tnv_id := generate_tnv_id(v_district_id);

    -- Decide final wing
    if p_wing_id is not null then
        v_final_wing_id := p_wing_id;
    elsif v_final_wing_id is null then
        v_final_wing_id := 1; -- default to Administration
    end if;

    -- 6. Update profile in single transaction
    update profiles
    set status = 'approved',
        role = p_role,
        wing_id = v_final_wing_id,
        tnv_id = v_tnv_id
    where id = p_profile_id;

    -- 7. Upsert verifications record
    insert into verifications (
        profile_id,
        total_score,
        recommended_role,
        approved_by,
        approved_at
    ) values (
        p_profile_id,
        v_total_score,
        p_role,
        v_admin_id,
        now()
    )
    on conflict (profile_id)
    do update set
        total_score = excluded.total_score,
        recommended_role = excluded.recommended_role,
        approved_by = excluded.approved_by,
        approved_at = excluded.approved_at;

    -- 8. Record in audit_log
    insert into audit_log (
        actor,
        action,
        target,
        detail,
        at
    ) values (
        v_admin_id,
        'approve_applicant',
        p_profile_id,
        jsonb_build_object(
            'total_score', v_total_score,
            'role', p_role,
            'wing_id', v_final_wing_id,
            'tnv_id', v_tnv_id,
            'questions_scored', v_scored_count
        ),
        now()
    );

    return jsonb_build_object(
        'success', true,
        'profile_id', p_profile_id,
        'status', 'approved',
        'role', p_role,
        'wing_id', v_final_wing_id,
        'tnv_id', v_tnv_id,
        'total_score', v_total_score,
        'full_name', v_full_name,
        'username', v_username,
        'email', v_email,
        'approved_by', v_admin_id,
        'approved_at', now()
    );
end;
$$;

grant execute on function approve_applicant_tx(uuid, app_role, int) to authenticated, service_role;

